import React from "react";
import "./ChildrenAndPetsCard.css"; // Import CSS

function ChildrenAndCard() {
  return (
    <div className="communication-card">
      {/* Paw Icon at the top left */}
      <img src="/Paw.png" alt="Paw Icon" className="paw-icon" />

      {/* Title */}
      <h3 className="card3-title">Children and pets</h3>

      {/* Description */}
      <p className="card3-text">
      Pets establish emotional attachments to children, and the relationship turns out positive in terms of affective aspects, in reinforcement of the child's personality.      </p>

      {/* Cat Icon at the bottom left */}
      <img src="/Dog2.png" alt="Cat Icon" className="dog-icon" />
    </div>
  );
}

export default CommunicationCard;
